4. //!
5. //! # Fixed-Size Bump Allocator
6. //!
7. //! A generic, `no_std`-compatible bump allocator that hands out fixed-size slots from a
8. //! statically reserved memory region (typically BSS). Each slot is allocated exactly once via an
9. //! atomic compare-and-swap index, making the allocator lock-free and safe for concurrent use.
10. //!
11. //! ## Key Types
12. //!
13. //! - [`BssStorage`] — unsafe trait implemented by the backing store provider.
14. //! - [`FixedSizeBumpAllocator`] — the allocator parameterised by unit size, alignment, and
15. //!   storage backend.
16. //! - [`BumpAllocError`] — error type returned when allocation fails.
17. //!
18. //! ## Usage
19. //!
20. //! 1. Define a static storage region and implement [`BssStorage`] for it.
21. //! 2. Create a `static` [`FixedSizeBumpAllocator`] with [`FixedSizeBumpAllocator::new()`].
22. //! 3. Call [`alloc()`](FixedSizeBumpAllocator::alloc) to obtain raw byte slots, or
23. //!    [`alloc_as()`](FixedSizeBumpAllocator::alloc_as) for typed `MaybeUninit<T>` slots.
24. //!
25. //! ## Example
26. //!
27. //! ```rust
28. //! use bump_allocator::{align_up, BssStorage, BumpAllocError, FixedSizeBumpAllocator};
29. //!
30. //! const UNIT_SIZE: usize = 64;
31. //! const UNIT_ALIGN: usize = 64;
32. //! const NUM_SLOTS: usize = 4;
33. //! const STRIDE: usize = match align_up(UNIT_SIZE, UNIT_ALIGN) {
34. //!     Some(v) => v,
35. //!     None => panic!("stride overflow"),
36. //! };
37. //! const STORAGE_SIZE: usize = NUM_SLOTS * STRIDE;
38. //!
39. //! #[repr(align(64))]
40. //! struct MyStorage {
41. //!     bytes: [u8; STORAGE_SIZE],
42. //! }
43. //!
44. //! static mut BACKING: MyStorage = MyStorage {
45. //!     bytes: [0; STORAGE_SIZE],
46. //! };
47. //!
48. //! struct MyBackend;
49. //!
50. //! // SAFETY: BACKING is a stable, properly aligned static region exclusively managed by
51. //! // the allocator.
52. //! unsafe impl BssStorage for MyBackend {
53. //!     const NUM_UNITS: usize = NUM_SLOTS;
54. //!     const STORAGE_SIZE: usize = STORAGE_SIZE;
55. //!
56. //!     fn as_mut_ptr() -> *mut u8 {
57. //!         unsafe { core::ptr::addr_of_mut!(BACKING.bytes) as *mut u8 }
58. //!     }
59. //! }
60. //!
61. //! // SAFETY: single allocator instance for `MyBackend`.
62. //! static ALLOCATOR: FixedSizeBumpAllocator<UNIT_SIZE, UNIT_ALIGN, MyBackend> =
63. //!     unsafe { FixedSizeBumpAllocator::new() };
64. //!
65. //! // Allocate raw byte slots.
66. //! let slot_a: &mut [u8; UNIT_SIZE] = ALLOCATOR.alloc().expect("slot a");
67. //! let slot_b: &mut [u8; UNIT_SIZE] = ALLOCATOR.alloc().expect("slot b");
68. //! assert_ne!(slot_a.as_ptr(), slot_b.as_ptr());
69. //!
70. //! // Allocate a typed slot (caller must initialise before reading).
71. //! let uninit: &mut core::mem::MaybeUninit<[u32; 16]> =
72. //!     unsafe { ALLOCATOR.alloc_as::<[u32; 16]>().expect("typed slot") };
73. //! uninit.write([0u32; 16]);
74. //! let typed: &mut [u32; 16] = unsafe { uninit.assume_init_mut() };
75. //! typed[0] = 42;
76. //! assert_eq!(typed[0], 42);
77. //! ```
78. 
79. //==================================================================================================
80. // Configuration
81. //==================================================================================================
82. 
83. #![cfg_attr(not(any(test, feature = "std")), no_std)]
84. 
85. //==================================================================================================
86. // Imports
87. //==================================================================================================
88. 
89. use ::core::{
90.     fmt,
91.     marker::PhantomData,
92.     mem::MaybeUninit,
93.     sync::atomic::{
94.         AtomicUsize,
95.         Ordering,
96.     },
97. };
98. use ::vstd::prelude::*;
99. 
100. // Include specifications.
101. #[cfg(verus_keep_ghost)]
102. include!("lib.spec.rs");
103. 
104. // Include proofs.
105. #[cfg(verus_keep_ghost)]
106. include!("lib.proof.rs");
107. 
108. //==================================================================================================
109. // Traits and Types
110. //==================================================================================================
111. 
112. ///
113. /// # Description
114. ///
115. /// Aligns `value` up to the next multiple of `alignment`.
116. ///
117. /// # Parameters
118. ///
119. /// - `value`: Value to align.
120. /// - `alignment`: Alignment boundary.
121. ///
122. /// # Returns
123. ///
124. /// Returns the aligned value, or `None` if `alignment` is zero or the computation overflows.
125. ///
126. #[verus_spec(result =>
127.     ensures
128.         match result {
129.             Some(r) => align_up_spec(value as nat, alignment as nat) == Some(r as nat),
130.             None => align_up_spec(value as nat, alignment as nat) is None,
131.         },
132. )]
133. pub const fn align_up(value: usize, alignment: usize) -> Option<usize> {
134.     if alignment == 0 {
135.         return None;
136.     }
137.     value.div_ceil(alignment).checked_mul(alignment)
138. }
139. 
140. ///
141. /// # Description
142. ///
143. /// Error type returned by [`FixedSizeBumpAllocator`] operations.
144. ///
145. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
146. pub enum BumpAllocError {
147.     /// Storage capacity exhausted.
148.     Exhausted,
149.     /// Type size does not match allocator unit size.
150.     SizeMismatch,
151.     /// Type alignment exceeds allocator alignment.
152.     AlignmentMismatch,
153.     /// Internal arithmetic overflow.
154.     Overflow,
155.     /// Computed slot exceeds storage bounds.
156.     OutOfBounds,
157.     /// Computed slot is not properly aligned.
158.     Misaligned,
159. }
160. 
161. impl fmt::Display for BumpAllocError {
162.     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
163.         match self {
164.             Self::Exhausted => write!(f, "fixed-size BSS allocator exhausted"),
165.             Self::SizeMismatch => write!(f, "type size does not match allocator unit size"),
166.             Self::AlignmentMismatch => write!(f, "type alignment exceeds allocator alignment"),
167.             Self::Overflow => write!(f, "allocator internal arithmetic overflow"),
168.             Self::OutOfBounds => write!(f, "allocator slot exceeds storage bounds"),
169.             Self::Misaligned => write!(f, "allocator returned misaligned slot"),
170.         }
171.     }
172. }
173. 
174. ///
175. /// # Description
176. ///
177. /// Backend trait for fixed-size allocators that draw memory from static storage.
178. ///
179. /// # Safety
180. ///
181. /// Implementers must guarantee that:
182. ///
183. /// - `as_mut_ptr()` returns a stable pointer to a backing region of at least `STORAGE_SIZE`
184. ///   bytes for the allocator lifetime.
185. /// - the backing region is writable and properly aligned for any allocation site that uses this
186. ///   backend.
187. /// - the backing region is exclusively managed by this allocator API, so creating `&'static mut`
188. ///   references from slots cannot alias with other mutable references.
189. ///
190. pub unsafe trait BssStorage {
191.     /// Number of fixed-size units that can be allocated.
192.     const NUM_UNITS: usize;
193. 
194.     /// Total size in bytes of the backing storage region.
195.     const STORAGE_SIZE: usize;
196. 
197.     /// Returns a mutable pointer to the beginning of the storage region.
198.     #[verus_spec]
199.     fn as_mut_ptr() -> *mut u8;
200. }
201. 
202. ///
203. /// # Description
204. ///
205. /// Generic fixed-size bump allocator over statically reserved memory.
206. ///
207. /// # Type Parameters
208. ///
209. /// - `N`: Unit size in bytes.
210. /// - `A`: Unit alignment in bytes.
211. /// - `S`: Backing storage provider.
212. ///
213. pub struct FixedSizeBumpAllocator<const N: usize, const A: usize, S: BssStorage> {
214.     /// Atomic bump index for the next available slot.
215.     next_slot: AtomicUsize,
216.     /// Marker for the backend storage provider.
217.     _storage: PhantomData<S>,
218. }
219. 
220. impl<const N: usize, const A: usize, S: BssStorage> FixedSizeBumpAllocator<N, A, S> {
221.     ///
222.     /// # Description
223.     ///
224.     /// Creates a new fixed-size bump allocator.
225.     ///
226.     /// # Returns
227.     ///
228.     /// Returns a new allocator.
229.     ///
230.     /// # Safety
231.     ///
232.     /// The caller must ensure that only **one** `FixedSizeBumpAllocator` instance exists for a
233.     /// given `S: BssStorage` backend at any time. Creating multiple allocators over the same
234.     /// backend causes independent bump counters, which leads to overlapping slot reservations
235.     /// and undefined behavior (multiple `&'static mut` references to the same memory).
236.     ///
237.     pub const unsafe fn new() -> Self {
238.         Self {
239.             next_slot: AtomicUsize::new(0),
240.             _storage: PhantomData,
241.         }
242.     }
243. 
244.     ///
245.     /// # Description
246.     ///
247.     /// Allocates the next fixed-size slot as a raw byte array.
248.     ///
249.     /// # Returns
250.     ///
251.     /// On success, returns a mutable reference to a unit-sized byte array.
252.     ///
253.     /// # Errors
254.     ///
255.     /// - [`BumpAllocError::Exhausted`] if storage capacity is exhausted.
256.     /// - [`BumpAllocError::Overflow`] if internal arithmetic overflows.
257.     /// - [`BumpAllocError::OutOfBounds`] if computed slot exceeds storage bounds.
258.     /// - [`BumpAllocError::Misaligned`] if computed slot is not properly aligned.
259.     ///
260.     pub fn alloc(&self) -> Result<&'static mut [u8; N], BumpAllocError> {
261.         // Reserve a slot index via compare-and-swap to avoid overshooting the counter.
262.         let idx: usize = loop {
263.             let current: usize = self.next_slot.load(Ordering::Acquire);
264.             if current >= S::NUM_UNITS {
265.                 return Err(BumpAllocError::Exhausted);
266.             }
267.             let next: usize = current.checked_add(1).ok_or(BumpAllocError::Overflow)?;
268.             if self
269.                 .next_slot
270.                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
271.                 .is_ok()
272.             {
273.                 break current;
274.             }
275.         };
276. 
277.         let stride: usize = align_up(N, A).ok_or(BumpAllocError::Overflow)?;
278.         let offset: usize = idx.checked_mul(stride).ok_or(BumpAllocError::Overflow)?;
279. 
280.         let base: usize = S::as_mut_ptr() as usize;
281.         let ptr: usize = base.checked_add(offset).ok_or(BumpAllocError::Overflow)?;
282.         let end: usize = ptr.checked_add(N).ok_or(BumpAllocError::Overflow)?;
283.         let storage_end: usize = base
284.             .checked_add(S::STORAGE_SIZE)
285.             .ok_or(BumpAllocError::Overflow)?;
286.         if end > storage_end {
287.             return Err(BumpAllocError::OutOfBounds);
288.         }
289.         if !ptr.is_multiple_of(A) {
290.             return Err(BumpAllocError::Misaligned);
291.         }
292. 
293.         // SAFETY: the backend contract guarantees valid stable storage; each slot index is handed
294.         // out at most once by atomic compare-and-swap.
295.         Ok(unsafe { &mut *(ptr as *mut [u8; N]) })
296.     }
297. 
298.     ///
299.     /// # Description
300.     ///
301.     /// Allocates the next fixed-size slot and reinterprets it as `MaybeUninit<T>`.
302.     ///
303.     /// # Returns
304.     ///
305.     /// On success, returns a mutable reference to an uninitialized `T`.
306.     ///
307.     /// # Errors
308.     ///
309.     /// - [`BumpAllocError::SizeMismatch`] if `size_of::<T>() != N`.
310.     /// - [`BumpAllocError::AlignmentMismatch`] if `align_of::<T>() > A`.
311.     /// - Any error from [`alloc()`](Self::alloc).
312.     ///
313.     /// # Safety
314.     ///
315.     /// The caller must initialise the returned `MaybeUninit<T>` before reading through it
316.     /// and ensure exclusive use of the returned reference.
317.     ///
318.     pub unsafe fn alloc_as<T>(&self) -> Result<&'static mut MaybeUninit<T>, BumpAllocError> {
319.         if core::mem::size_of::<T>() != N {
320.             return Err(BumpAllocError::SizeMismatch);
321.         }
322.         if core::mem::align_of::<T>() > A {
323.             return Err(BumpAllocError::AlignmentMismatch);
324.         }
325. 
326.         let slot: &'static mut [u8; N] = self.alloc()?;
327.         // SAFETY: size/alignment checks above guarantee this cast is valid.
328.         Ok(unsafe { &mut *(slot.as_mut_ptr() as *mut MaybeUninit<T>) })
329.     }
330. }
331. 
332. impl<const N: usize, const A: usize, S: BssStorage> Default for FixedSizeBumpAllocator<N, A, S> {
333.     fn default() -> Self {
334.         // SAFETY: caller is responsible for the singleton invariant.
335.         unsafe { Self::new() }
336.     }
337. }
338. 
